    type reg_reg_type71 is array (0 to 1) of std_logic_vector(71 downto 0);
    signal registered_registered_bram1or_o,registered_registered_bram2or_o,registered_registered_bram3or_o,registered_registered_bram4or_o:reg_reg_type71       := (others=>(others=>'0'));
    signal registered_registered_bram1and_o,registered_registered_bram2and_o,registered_registered_bram3and_o,registered_registered_bram4and_o:reg_reg_type71   := (others=>(others=>'0'));   
    signal registered_bram1nr_o,registered_bram2nr_o,registered_bram3nr_o,registered_bram4nr_o:reg_reg_type71       := (others=>(others=>'0'));

    -- Unified array for easier access.
    type reg_reg_type is array (0 to 1) of std_logic_vector(287 downto 0);
    signal registered_nominalR_en,registered_registered_nominalOR_en,registered_registered_nominalAND_en: reg_reg_type := (others=>(others=>'0'));

    -- Signals for nominalCSR BRAM access. 
    signal csr_input1,csr_input2:std_logic_vector(15 downto 0);
    signal csr_input            : std_logic_vector(31 downto 0);
    signal csr_output1,csr_output2:std_logic_vector(15 downto 0);
    signal csr_output           : std_logic_vector(31 downto 0);
    signal registered_csr_output: std_logic_vector(31 downto 0);

    -- Auxiliar signals for exception detection and DSP control.
    signal exceptionRO,exceptionPriv: std_logic;
    signal exceptionR,exceptionW    : std_logic;
    signal bram3out : std_logic_vector(XLEN/4-1 downto 0);
    signal nominalRead : std_logic_vector(XLEN/4-1 downto 0);
    signal registered_nominalRead : std_logic_vector(XLEN/4-1 downto 0);
    signal NOTtopRead : std_logic;
    signal registered_NOTtopRead : std_logic_vector(XLEN/4-1 downto 0);
    signal registered_registered_NOTtopRead : std_logic_vector(XLEN/2-1 downto 0);

    -- Auxiliar signals for DSP control and DSP muxing.
    signal rstAluDSP : std_logic_vector (XLEN/4-1 downto 0) :=(others=>'0');
    type ctrlDSP_type is array (XLEN/2-1 downto 0) of std_logic_vector(3 downto 0);
    signal ctrlAluDSP : ctrlDSP_type:= (others=>"0011");
    signal gprMux : std_logic_vector(XLEN-1 downto 0):=XLEN_ZERO;
    signal csrMux : std_logic_vector(XLEN-1 downto 0):=XLEN_ZERO;
    type outDSP_type is array (XLEN-1 downto 0) of std_logic_vector(47 downto 0);
    signal data_out : std_logic_vector(XLEN-1 downto 0):=XLEN_ZERO; 
    signal dsp_out : outDSP_type; 
    type dspInAux_type is array (XLEN-1 downto 0) of std_logic_vector(95 downto 0);
    signal dspInAux:dspInAux_type;
    type dspIn_type is array (XLEN-1 downto 0) of std_logic_vector(64 downto 0);
    signal registered_dspIN: dspIn_type;
    type dummyCARRY_type is array ((XLEN*65)-1 downto 0) of std_logic_vector(3 downto 0);
    signal dummycarryCO:dummyCARRY_type;
    signal dummycarryO:dummyCARRY_type;
    type dummyDSP_type is array (XLEN-1 downto 0) of std_logic_vector(3 downto 0);
    signal dummydsp,reg_dummydsp:dummyDSP_type := (others=>(others=>'0'));

    -- Auxiliar attributes to direct synthesis. 
    attribute rom_style : string;
    attribute rom_style of ROM1 : signal is "block";
    attribute rom_style of ROM1_R : signal is "block";
    attribute rom_style of ROM1_A : signal is "block";
    attribute rom_style of ROM2 : signal is "block";
    attribute rom_style of ROM2_R : signal is "block";
    attribute rom_style of ROM2_A : signal is "block";
    attribute rom_style of ROM3 : signal is "block";
    attribute rom_style of ROM3_R : signal is "block";
    attribute rom_style of ROM3_A : signal is "block";
    attribute rom_style of ROM4 : signal is "block";
    attribute rom_style of ROM4_R : signal is "block";
    attribute rom_style of ROM4_A : signal is "block";

    attribute ram_style : string;
    attribute ram_style of CSRs1 : signal is "block";
    attribute ram_style of CSRs2 : signal is "block";
    
    attribute max_fanout : integer;
    attribute max_fanout of nominalRead:signal is 1;

    -- Auxiliary functions.
    function get_valid_address(a:integer) return integer is
    begin
        if    a >= 0   and a < 64  then
            return a;
        elsif a >= 64  and a < 128 then
            return a+8;
        elsif a >= 128 and a < 189 then
            return a+8+8;
        elsif a >= 189 and a < 259 then
            return a+8+8+11;
        else
            return 100000+a;
        end if;
    end function get_valid_address;

    function get_std_from_array(a : parregmux_type; b:integer) return std_logic_vector is
        variable ret : std_logic_vector(64 downto 0) := (others => '0');
    begin
        for i in a'range loop
            ret(i) := a(i)(b);
        end loop;
        return ret;
    end function get_std_from_array;

begin

    -- Obtaining the addresses for each stage with one fewer bit since we only implement modes M and U.
    address_simp_id <= inputs.DEC_outputs.regCSR(11 downto 10)   & inputs.DEC_outputs.regCSR(8)   & inputs.DEC_outputs.regCSR(7 downto 0);
    address_simp_ex <= inputs.RIDEX_outputs.regCSR(11 downto 10) & inputs.RIDEX_outputs.regCSR(8) & inputs.RIDEX_outputs.regCSR(7 downto 0);
    address_simp_mem<= inputs.REXMEM_outputs.regCSR(11 downto 10)& inputs.REXMEM_outputs.regCSR(8)& inputs.REXMEM_outputs.regCSR(7 downto 0);
    address_simp_wb <= inputs.RMEMWB_outputs.regCSR(11 downto 10)& inputs.RMEMWB_outputs.regCSR(8)& inputs.RMEMWB_outputs.regCSR(7 downto 0);

    bankMEM     <= address_simp_mem(8 downto 8)  & address_simp_mem(5 downto 5);
    bankEX      <= address_simp_ex (8 downto 8)  & address_simp_ex (5 downto 5);
    bankID      <= address_simp_id (8 downto 8)  & address_simp_id (5 downto 5);
    addressEX   <= address_simp_ex (10 downto 9) & address_simp_ex(7 downto 6) & address_simp_ex(4  downto 0);
    addressID   <= address_simp_id (10 downto 9) & address_simp_id(7 downto 6) & address_simp_id(4  downto 0);

    -- Processes for the creation of the one-hot decorders.
    process(I_clock)
    begin
        if rising_edge(I_clock) then
            if (inputs.DEC_outputs.needsCSROROp = '1') then
                bram1or_o <= ROM1(to_integer(unsigned(addressID)));
            else
                bram1or_o <= (others => '0');
            end if;
        end if;
    end process;
    process(I_clock)
    begin
        if rising_edge(I_clock) then
            registered_bram1or_o    <= bram1or_o;
            if rst1EX = '1' then
                registered_bram1or_o <= (others=>'0');
            end if;
        end if;
    end process;
    process(I_clock)
    begin
        if rising_edge(I_clock) then
            for i in 0 to 1 loop
                registered_registered_bram1or_o(i) <= registered_bram1or_o;
            end loop;
        end if;
    end process;

    process(I_clock)
    begin
        if rising_edge(I_clock) then
            if (inputs.DEC_outputs.needsCSROROp = '1') then
                bram2or_o <= ROM2(to_integer(unsigned(addressID)));
            else
                bram2or_o <= (others => '0');
            end if;
        end if;
    end process;
    process(I_clock)
    begin
        if rising_edge(I_clock) then
            registered_bram2or_o    <= bram2or_o;
            if rst2EX = '1' then
                registered_bram2or_o <= (others=>'0');
            end if;
        end if;
    end process;
    process(I_clock)
    begin
        if rising_edge(I_clock) then
            for i in 0 to 1 loop
                registered_registered_bram2or_o(i) <= registered_bram2or_o;
            end loop;
        end if;
    end process;

    process(I_clock)
    begin
        if rising_edge(I_clock) then
            if (inputs.DEC_outputs.needsCSROROp = '1') then
                bram3or_o <= ROM3(to_integer(unsigned(addressID)));
            else
                bram3or_o <= (others => '0');
            end if;
        end if;
    end process;
    process(I_clock)
    begin
        if rising_edge(I_clock) then
            registered_bram3or_o    <= bram3or_o;
            if rst3EX = '1' then
                registered_bram3or_o <= (others=>'0');
            end if;
        end if;
    end process;
    process(I_clock)
    begin
        if rising_edge(I_clock) then
            for i in 0 to 1 loop
                registered_registered_bram3or_o(i) <= registered_bram3or_o;
            end loop;
        end if;
    end process;

    process(I_clock)
    begin
        if rising_edge(I_clock) then
            if (inputs.DEC_outputs.needsCSROROp = '1') then
                bram4or_o <= ROM4(to_integer(unsigned(addressID)));
            else
                bram4or_o <= (others => '0');
            end if;
        end if;
    end process;
    process(I_clock)
    begin
        if rising_edge(I_clock) then
            registered_bram4or_o    <= bram4or_o;
            if rst4EX = '1' then
                registered_bram4or_o <= (others=>'0');
            end if;
        end if;
    end process;
    process(I_clock)
    begin
        if rising_edge(I_clock) then
            for i in 0 to 1 loop
                registered_registered_bram4or_o(i) <= registered_bram4or_o;
            end loop;
        end if;
    end process;

    process(I_clock)
    begin
        if rising_edge(I_clock) then
            if (inputs.DEC_outputs.needsCSRANDOp = '1') then
                bram1and_o <= ROM1_A(to_integer(unsigned(addressID)));
            else
                bram1and_o <= (others => '0');
            end if;
        end if;
    end process;
    process(I_clock)
    begin
        if rising_edge(I_clock) then
            registered_bram1and_o   <= bram1and_o;
            if rst1EX = '1' then
                registered_bram1and_o <= (others=>'0');
            end if;
        end if;
    end process;
    process(I_clock)
    begin
        if rising_edge(I_clock) then
            for i in 0 to 1 loop
                registered_registered_bram1and_o(i) <= registered_bram1and_o;
            end loop;
        end if;
    end process;

    process(I_clock)
    begin
        if rising_edge(I_clock) then
            if (inputs.DEC_outputs.needsCSRANDOp = '1') then
                bram2and_o <= ROM2_A(to_integer(unsigned(addressID)));
            else
                bram2and_o <= (others => '0');
            end if;
        end if;
    end process;
    process(I_clock)
    begin
        if rising_edge(I_clock) then
            registered_bram2and_o   <= bram2and_o;
            if rst2EX = '1' then
                registered_bram2and_o <= (others=>'0');
            end if;
        end if;
    end process;
    process(I_clock)
    begin
        if rising_edge(I_clock) then
            for i in 0 to 1 loop
                registered_registered_bram2and_o(i) <= registered_bram2and_o;
            end loop;
        end if;
    end process;

    process(I_clock)
    begin
        if rising_edge(I_clock) then
            if (inputs.DEC_outputs.needsCSRANDOp = '1') then
                bram3and_o <= ROM3_A(to_integer(unsigned(addressID)));
            else
                bram3and_o <= (others => '0');
            end if;
        end if;
    end process;
    process(I_clock)
    begin
        if rising_edge(I_clock) then
            registered_bram3and_o   <= bram3and_o;
            if rst3EX = '1' then
                registered_bram3and_o <= (others=>'0');
            end if;
        end if;
    end process;
    process(I_clock)
    begin
        if rising_edge(I_clock) then
            for i in 0 to 1 loop
                registered_registered_bram3and_o(i) <= registered_bram3and_o;
            end loop;
        end if;
    end process;

    process(I_clock)
    begin
        if rising_edge(I_clock) then
            if (inputs.DEC_outputs.needsCSRANDOp = '1') then
                bram4and_o <= ROM4_A(to_integer(unsigned(addressID)));
            else
                bram4and_o <= (others => '0');
            end if;
        end if;
    end process;
    process(I_clock)
    begin
        if rising_edge(I_clock) then
            registered_bram4and_o   <= bram4and_o;
            if rst4EX = '1' then
                registered_bram4and_o <= (others=>'0');
            end if;
        end if;
    end process;
    process(I_clock)
    begin
        if rising_edge(I_clock) then
            for i in 0 to 1 loop
                registered_registered_bram4and_o(i) <= registered_bram4and_o;
            end loop;
        end if;
    end process;

    process(I_clock)
    begin
        if rising_edge(I_clock) then
            if (inputs.DEC_outputs.validOpCSRR = '1') then
                bram1nr_o <= ROM1_R(to_integer(unsigned(addressID)));
                if rst1ID = '1' then
                    bram1nr_o <= (others => '1');
                end if;
            else bram1nr_o <= (others => '1');
            end if;
        end if;
    end process;
    process(I_clock)
    begin
        if rising_edge(I_clock) then
            for i in 0 to 1 loop
                registered_bram1nr_o(i)    <= bram1nr_o;
            end loop;
        end if;
    end process;

    process(I_clock)
    begin
        if rising_edge(I_clock) then
            if (inputs.DEC_outputs.validOpCSRR = '1') then
                bram2nr_o <= ROM2_R(to_integer(unsigned(addressID)));
                if rst2ID = '1' then
                    bram2nr_o <= (others => '1');
                end if;
            else bram2nr_o <= (others => '1');
            end if;
        end if;
    end process;
    process(I_clock)
    begin
        if rising_edge(I_clock) then
            for i in 0 to 1 loop
                registered_bram2nr_o(i)    <= bram2nr_o;
            end loop;
        end if;
    end process;

    process(I_clock)
    begin
        if rising_edge(I_clock) then
            if (inputs.DEC_outputs.validOpCSRR = '1') then
                bram3nr_o <= ROM3_R(to_integer(unsigned(addressID)));
                if rst3ID = '1' then
                    bram3nr_o <= (others => '1');
                end if;
            else bram3nr_o <= (others => '1');
            end if;
        end if;
    end process;
    process(I_clock)
    begin
        if rising_edge(I_clock) then
            for i in 0 to 1 loop
                registered_bram3nr_o(i)    <= bram3nr_o;
            end loop;
        end if;
    end process;

    process(I_clock)
    begin
        if rising_edge(I_clock) then
            if (inputs.DEC_outputs.validOpCSRR = '1') then
                bram4nr_o <= ROM4_R(to_integer(unsigned(addressID)));
                if rst4ID = '1' then
                    bram4nr_o <= (others => '1');
                end if;
            else bram4nr_o <= (others => '1');
            end if;
        end if;
    end process;
    process(I_clock)
    begin
        if rising_edge(I_clock) then
            for i in 0 to 1 loop
                registered_bram4nr_o(i)    <= bram4nr_o;
            end loop;
        end if;
    end process;


    -- Resets to only obtain the output from one bank.
    process(bankID)
    begin
        rst1ID <= '1';
        rst2ID <= '1';
        rst3ID <= '1';
        rst4ID <= '1';
        case bankID is
            when "00" => rst1ID <= '0';
            when "01" => rst2ID <= '0';
            when "10" => rst3ID <= '0';
            when "11" => rst4ID <= '0';
            when others => rst1ID <= 'X';rst2ID <= 'X';rst3ID <= 'X';rst4ID <= 'X';
        end case;
    end process;
    process(bankEX)
    begin
        rst1EX <= '1';
        rst2EX <= '1';
        rst3EX <= '1';
        rst4EX <= '1';
        case bankEX is
            when "00" => rst1EX <= '0';
            when "01" => rst2EX <= '0';
            when "10" => rst3EX <= '0';
            when "11" => rst4EX <= '0';
            when others => rst1EX <= 'X';rst2EX <= 'X';rst3EX <= 'X';rst4EX <= 'X';
        end case;
    end process;


    -- Fusing all outputs into a single array for easier access.
    reg_reg: for i in 0 to 1 generate
        registered_registered_nominalOR_en(i)(71 downto 0)      <= registered_registered_bram1or_o(i);
        registered_registered_nominalOR_en(i)(143 downto 72)    <= registered_registered_bram2or_o(i);
        registered_registered_nominalOR_en(i)(215 downto 144)   <= registered_registered_bram4or_o(i);  -- Changing the order of brams 3 and 4 to make all top entries of the DSP be in bram3.
        registered_registered_nominalOR_en(i)(287 downto 216)   <= registered_registered_bram3or_o(i);  -- Changing the order of brams 3 and 4 to make all top entries of the DSP be in bram3.
        registered_registered_nominalAND_en(i)(71 downto 0)     <= registered_registered_bram1and_o(i);
        registered_registered_nominalAND_en(i)(143 downto 72)   <= registered_registered_bram2and_o(i);
        registered_registered_nominalAND_en(i)(215 downto 144)  <= registered_registered_bram4and_o(i); -- Changing the order of brams 3 and 4 to make all top entries of the DSP be in bram3.
        registered_registered_nominalAND_en(i)(287 downto 216)  <= registered_registered_bram3and_o(i); -- Changing the order of brams 3 and 4 to make all top entries of the DSP be in bram3.
        registered_nominalR_en(i)(71 downto 0)    <= registered_bram1nr_o(i);
        registered_nominalR_en(i)(143 downto 72)  <= registered_bram2nr_o(i);
        registered_nominalR_en(i)(215 downto 144) <= registered_bram4nr_o(i); -- Changing the order of brams 3 and 4 to make all top entries of the DSP be in bram3.
        registered_nominalR_en(i)(287 downto 216) <= registered_bram3nr_o(i); -- Changing the order of brams 3 and 4 to make all top entries of the DSP be in bram3.
    end generate;
    
    -- Calculation of exceptions conditions.
    -- Access to illegal CSR.
    exceptionR <= not registered_bram1nr_o(0) (71) or not registered_bram2nr_o(0) (71) or registered_bram3nr_o(0) (71) or not registered_bram4nr_o(0) (71);
    exceptionW <= registered_bram1or_o (71) or registered_bram2or_o (71) or registered_bram3or_o (71) or registered_bram4or_o (71) or 
                  registered_bram1and_o(71) or registered_bram2and_o(71) or registered_bram3and_o(71) or registered_bram4and_o(71);

    -- Access to read-only CSR.
    exceptionRO <= '1' when inputs.REXMEM_outputs.validOPCSRW='1' and inputs.REXMEM_outputs.regCSR(11 downto 10)="11" else
                   '0';
    -- Access to CSR from another privilege level.
    exceptionPriv<='1' when (inputs.REXMEM_outputs.validOPCSRW='1' or inputs.REXMEM_outputs.validOPCSRR='1') and inputs.REXMEM_outputs.regCSR(9 downto 8)<=inputs.PROCIFace_outputs.PLevel else
                   '0';


    -- Calculation of auxiliar signals for DSP muxing.
    nominalRead_gen: for j in XLEN/4-1 downto 0 generate
        bram3out(j) <= (not bram3nr_o (71) and NOTtopRead);
        nominalRead(j)<=not bram1nr_o (70) or not bram2nr_o (70) or bram3out(j) or not bram4nr_o (70);
        registered_nominalRead(j)<= nominalRead(j) when rising_edge(I_clock);
    end generate;

    NOTtopRead<=bram3nr_o(70);

    registered_NOTtopRead<=(others=>NOTtopRead) when rising_edge(I_clock);

    process(I_clock)
    begin
        if rising_edge (I_clock) then
            for i in XLEN/4-1 downto 0 loop
                registered_registered_NOTtopRead(2*i)<=registered_NOTtopRead(i);
                registered_registered_NOTtopRead(2*i+1)<=registered_NOTtopRead(i);
            end loop;
        end if;
    end process;


    -- BRAM for nominal CSR access.
    process(I_clock)
    begin
        if rising_edge(I_clock) then
                    csr_output1 <= CSRs1(to_integer(unsigned(address_simp_wb)));
                    csr_output2 <= CSRs2(to_integer(unsigned(address_simp_wb)));
                if (inputs.RMEMWB_outputs.validOpCSRW = '1') then
                    -- BRAM with write-first mode.
                    CSRs1(to_integer(unsigned(address_simp_wb))) <= csr_input1;
                    CSRs2(to_integer(unsigned(address_simp_wb))) <= csr_input2;
                    csr_output1 <= csr_input1;
                    csr_output2 <= csr_input2;
                end if;
            end if;
    end process;
    
    csr_output<=csr_output2&csr_output1;

    process(I_clock)
    begin
        if rising_edge(I_clock) then
            registered_csr_output <= csr_output;
        end if;
    end process;

    -- Calculation of the input to nominalCSR depending on the instruction (write, set or clear).
    process(inputs.RMEMWB_outputs.needsCSROROp,inputs.RMEMWB_outputs.needsCSRANDOp,inputs.GPRs_outputs.regS1_valueWB(XLEN-1 downto 0),registered_csr_output)
        variable regS1_csr_input      : std_logic_vector(31 downto 0);
    begin
        for j in XLEN-1 downto 0 loop
            regS1_csr_input(j) := inputs.GPRs_outputs.regS1_valueWB(3*j);
        end loop;
        if inputs.RMEMWB_outputs.needsCSROROp(0) = '1' then
            if inputs.RMEMWB_outputs.needsCSRANDOp(0) = '1' then
                csr_input <= regS1_csr_input;
            else
                csr_input <= registered_csr_output or regS1_csr_input;
            end if;
        else
            if inputs.RMEMWB_outputs.needsCSRANDOp(0) = '1' then
                csr_input <= registered_csr_output and regS1_csr_input;
            else
                csr_input <= registered_csr_output ;
            end if;
        end if;
    end process;
    csr_input1<=csr_input(15 downto 0);
    csr_input2<=csr_input(31 downto 16);



    -- Loop to generate parregs, DSPmuxes, etc. per bit width. 32 in our case.
    width : for j in XLEN-1 downto 0 generate

        -- Loop to generate selection LUTs, parregs and CARRY4s. Thus, this is per CARRY mux. 65 in our case, so 4 LUTs and FFs per loop to achieve 259 parregs. 
        mux_inst : for i in parregs_mux'range generate
        attribute RLOC  :string;
        attribute U_SET  :string;
        attribute BEL  :string;

        -- Attributes to achieve RLOC structure with 4 LUTs, 4 FF and 1 CARRY per slice. Continues below, to accommodate corner cases.
        attribute U_SET of LUT6_D_inst0 : label is "setI"& integer'image(i) & "J" & integer'image(j);
        attribute U_SET of LUT6_D_inst1 : label is "setI"& integer'image(i) & "J" & integer'image(j);
        attribute U_SET of LUT6_D_inst2 : label is "setI"& integer'image(i) & "J" & integer'image(j);
        attribute U_SET of FDRE_inst0   : label is "setI"& integer'image(i) & "J" & integer'image(j);
        attribute U_SET of FDRE_inst1   : label is "setI"& integer'image(i) & "J" & integer'image(j);
        attribute U_SET of FDRE_inst2   : label is "setI"& integer'image(i) & "J" & integer'image(j);
        attribute RLOC of LUT6_D_inst0: label is "X0Y0";
        attribute RLOC of LUT6_D_inst1: label is "X0Y0";
        attribute RLOC of LUT6_D_inst2: label is "X0Y0";
        attribute RLOC of FDRE_inst0 : label is "X0Y0";
        attribute RLOC of FDRE_inst1 : label is "X0Y0";
        attribute RLOC of FDRE_inst2 : label is "X0Y0";
        attribute BEL of FDRE_inst2 : label is "CFF";
        attribute BEL of FDRE_inst1 : label is "BFF";
        attribute BEL of FDRE_inst0 : label is "AFF";

        begin
            -- Forced to instantiante because otherwise Vivado does not let you to create RLOC structure in VHDL.
            -- TODO: An improvement would be writing this in processes and creating the RLOC in TCL macros. 
            LUT6_D_inst0 : LUT6_2
            generic map (
                -- When not reading (I5='1') then O6='1'; when reading (I5='0') then O6=O5. This works in active-low logic.
                -- When OR&AND=I3&I4="11", we are writing to the CSR, so O5='regS1_value' (I2).
                -- When only one of them is '1', we are setting or clearing the parreg (O5) based on its former value (I0) and I2.
                -- When neither OR or AND, we could be having a parallel write, or no operation. In this case, if regS1 is set (I2='1')
                -- then the parallel write is ocurring, so O5=I1, otherwise, O5=I0.
                INIT => X"FFFFFFFFF0A0FACA")
            port map (
                O6 => parregs_and(4*i)(j),
                O5 => parregs_in(4*i)(j),
                I0 => parregs(4*i+0)(j),
                I1 => inputs.PROCIFace_outputs.special(4*i+0)(j),
                I2 => inputs.GPRs_outputs.regS1_valueWB(3*j+((4*i+0)/87)),
                I3 => registered_registered_nominalOR_en(j/32)(get_valid_address(4*i+0)),
                I4 => registered_registered_nominalAND_en(j/32)(get_valid_address(4*i+0)),
                I5 => registered_nominalR_en(j/16)(get_valid_address(4*i+0))
            );
            LUT6_D_inst1 : LUT6_2
            generic map (
                INIT => X"FFFFFFFFF0A0FACA")
            port map (
                O6 => parregs_and(4*i+1)(j),
                O5 => parregs_in(4*i+1)(j),
                I0 => parregs(4*i+1)(j),
                I1 => inputs.PROCIFace_outputs.special(4*i+1)(j),
                I2 => inputs.GPRs_outputs.regS1_valueWB(3*j+((4*i+1)/87)),
                I3 => registered_registered_nominalOR_en(j/32)(get_valid_address(4*i+1)),
                I4 => registered_registered_nominalAND_en(j/32)(get_valid_address(4*i+1)),
                I5 => registered_nominalR_en(j/16)(get_valid_address(4*i+1))
            );
            LUT6_D_inst2 : LUT6_2
            generic map (
                INIT => X"FFFFFFFFF0A0FACA")
            port map (
                O6 => parregs_and(4*i+2)(j),
                O5 => parregs_in(4*i+2)(j),
                I0 => parregs(4*i+2)(j),
                I1 => inputs.PROCIFace_outputs.special(4*i+2)(j),
                I2 => inputs.GPRs_outputs.regS1_valueWB(3*j+((4*i+2)/87)),
                I3 => registered_registered_nominalOR_en(j/32)(get_valid_address(4*i+2)),
                I4 => registered_registered_nominalAND_en(j/32)(get_valid_address(4*i+2)),
                I5 => registered_nominalR_en(j/16)(get_valid_address(4*i+2))
            );
            LUT6_D_inst3:if 4*i+3 < 259 generate
            attribute U_SET of LUT6_D_inst3: label is "setI"& integer'image(i) & "J" & integer'image(j);
            attribute RLOC  of LUT6_D_inst3: label is "X0Y0";
            begin
                LUT6_D_inst3 : LUT6_2
                generic map (
                    INIT => X"FFFFFFFFF0A0FACA")
                port map (
                    O6 => parregs_and(4*i+3)(j),
                    O5 => parregs_in(4*i+3)(j),
                    I0 => parregs(4*i+3)(j),
                    I1 => inputs.PROCIFace_outputs.special(4*i+3)(j),
                    I2 => inputs.GPRs_outputs.regS1_valueWB(3*j+((4*i+3)/87)),
                    I3 => registered_registered_nominalOR_en(j/32)(get_valid_address(4*i+3)),
                    I4 => registered_registered_nominalAND_en(j/32)(get_valid_address(4*i+3)),
                    I5 => registered_nominalR_en(j/16)(get_valid_address(4*i+3))
                );
            end generate;

            -- These are the actual parregs.
            FDRE_inst0 : FDRE
            generic map (
                INIT => '0')    -- Initial value of register ('0' or '1')  
            port map (
                Q => parregs(4*i+0)(j),   -- Data output
                C => I_clock,             -- Clock input
                CE=> '1',                 -- Clock enable input
                R => '0',                 -- Synchronous reset input
                D => parregs_in(4*i+0)(j) -- Data input
            );
            FDRE_inst1 : FDRE
            generic map (
                INIT => '0')    -- Initial value of register ('0' or '1')  
            port map (
                Q => parregs(4*i+1)(j),   -- Data output
                C => I_clock,             -- Clock input
                CE=> '1',                 -- Clock enable input
                R => '0',                 -- Synchronous reset input
                D => parregs_in(4*i+1)(j) -- Data input
            );
            FDRE_inst2 : FDRE
            generic map (
                INIT => '0')    -- Initial value of register ('0' or '1')  
            port map (
                Q => parregs(4*i+2)(j),   -- Data output
                C => I_clock,             -- Clock input
                CE=> '1',                 -- Clock enable input
                R => '0',                 -- Synchronous reset input
                D => parregs_in(4*i+2)(j) -- Data input
            );
            FDRE_inst3:if 4*i+3 < 259 generate
                attribute U_SET of FDRE_inst3 : label is "setI"& integer'image(i) & "J" & integer'image(j);
                attribute RLOC  of FDRE_inst3 : label is "X0Y0";
                begin
            FDRE_inst3 : FDRE
            generic map (
                INIT => '0')    -- Initial value of register ('0' or '1')  
            port map (
                Q => parregs(4*i+3)(j),   -- Data output
                C => I_clock,             -- Clock input
                CE=> '1',                 -- Clock enable input
                R => '0',                 -- Synchronous reset input
                D => parregs_in(4*i+3)(j) -- Data input
            );
            end generate;

            -- CARRY4 mux so that the 259 reads can be reduced to 65 in the same cycle as the write to the CSR.
            CARRY4_inst:if 4*i+3 < 259 generate
            attribute U_SET of CARRY4_inst : label is "setI"& integer'image(i) & "J" & integer'image(j);
            attribute RLOC  of CARRY4_inst : label is "X0Y0";
            begin
                CARRY4_inst : CARRY4
                port map (
                    CO => dummycarryCO(32*i+j), -- Only CO3 is used.
                    O  => dummycarryO(32*i+j),  -- Unused.
                    CI     => '1', -- '1' to allow the read to pass.
                    CYINIT => '1', -- Unused
                    DI(0)  => parregs_in(4*i+0)(j),     -- 05 from LUT6_D_inst0.
                    DI(1)  => parregs_in(4*i+1)(j),     -- 05 from LUT6_D_inst1.
                    DI(2)  => parregs_in(4*i+2)(j),     -- 05 from LUT6_D_inst2.
                    DI(3)  => parregs_in(4*i+3)(j),     -- 05 from LUT6_D_inst3.
                    S(0)   => parregs_and(4*i+0)(j),    -- 06 from LUT6_D_inst0.
                    S(1)   => parregs_and(4*i+1)(j),    -- 06 from LUT6_D_inst1.
                    S(2)   => parregs_and(4*i+2)(j),    -- 06 from LUT6_D_inst2.
                    S(3)   => parregs_and(4*i+3)(j)     -- 06 from LUT6_D_inst3.
                );
            end generate;
            CARRY4_inst1:if 4*i+3 = 259 generate
            attribute U_SET of CARRY4_inst : label is "setI"& integer'image(i) & "J" & integer'image(j);
            attribute RLOC  of CARRY4_inst : label is "X0Y0";
            begin
                CARRY4_inst : CARRY4
                port map (
                    CO => dummycarryCO(32*i+j),  -- Only CO3 is used.
                    O  => dummycarryO(32*i+j),   -- Unused.
                    CI     => '1', -- '1' to allow the read to pass.
                    CYINIT => '1', -- Unused.
                    DI(0)  => parregs_in(4*i+0)(j), -- 05 from LUT6_D_inst0.
                    DI(1)  => parregs_in(4*i+1)(j), -- 05 from LUT6_D_inst1.
                    DI(2)  => parregs_in(4*i+2)(j), -- 05 from LUT6_D_inst2.
                    DI(3)  => '1',                  -- Unused.
                    S(0)   => parregs_and(4*i+0)(j),-- 06 from LUT6_D_inst0.
                    S(1)   => parregs_and(4*i+1)(j),-- 06 from LUT6_D_inst1.
                    S(2)   => parregs_and(4*i+2)(j),-- 06 from LUT6_D_inst2.
                    S(3)   => '1'                   -- Unused.
                );
            end generate;

            -- Output from the CARRY4 which is fed to a FF. There are 65*32 of them.
            -- This contains the value in case any of the parregs corresponding to the 
            -- RLOC structure of a slice have been read, or '1'. Thus, in active-low 
            -- logic, or the actual value.
            parregs_mux(i)(j)<=dummycarryCO(32*i+j)(3);
            FDRE_inst4 : FDRE
            generic map (
                INIT => '0') -- Initial value of register ('0' or '1')  
            port map (
                Q => registered_parregs_mux(i)(j),     -- Data output
                C => I_clock,             -- Clock input
                CE=> '1',                 -- Clock enable input
                R => '0',                 -- Synchronous reset input
                D => parregs_mux(i)(j)    -- Data input
            );

            -- Outputs to the processor interface.
            outputs.special(4*i+0)(j)<=parregs(4*i+0)(j);
            outputs.special(4*i+1)(j)<=parregs(4*i+1)(j);
            outputs.special(4*i+2)(j)<=parregs(4*i+2)(j);
            special_out:if 4*i+3 < 259 generate
                outputs.special(4*i+3)(j)<=parregs(4*i+3)(j);
            end generate;
        end generate;
        -- End of the intantiations for the slices, but we are still inside the instantiation loop for the bit width.

        -- Preparing all inputs to the DSPs 
        registered_dspIN(j)(64 downto 0) <= get_std_from_array(registered_parregs_mux,j)(64 downto 0);
        gprMux(j)<= inputs.RMEMWB_outputs.data(j);
        process(I_clock)
        begin
            if rising_edge(I_clock) then
                if registered_nominalRead(j/4) = '1' then
                    csrMux(j)<= not csr_output(j) and not rstAluDSP(j/4);
                else
                    csrMux(j)<= not rstALUDSP(j/4);
                end if;
            end if;
        end process;

        -- Uniting all inputs to the DSP in a single array.
        dspInAux(j)(95 downto 48) <= "11111111111111111111111111111"& registered_dspIN(j)(64 downto 48) & gprMux(j) & csrMux(j);
        dspInAux(j)(47 downto 0)  <=registered_dspIN(j)(47 downto 0);

        -- Control inputs for the DSPs. To better understand this see doc/ folder.
        rstAluDSP(j/4)<=(not registered_nominalRead(j/4)) and (inputs.REXMEM_outputs.validOpCSRR and registered_NOTtopRead(j/4));
        ctrlAluDSP(j/2)<="00"&registered_registered_NOTtopRead(j/2)&'1';

        -- DSP instantiations.
        DSP48E1_inst : DSP48E1
        generic map (
            -- Feature Control Attributes: Data Path Selection
            A_INPUT   => "DIRECT",                -- Selects A input source, "DIRECT" (A port) or "CASCADE" (ACIN port)
            B_INPUT   => "DIRECT",                -- Selects B input source, "DIRECT" (B port) or "CASCADE" (BCIN port)
            USE_DPORT => FALSE,                   -- Select D port usage (TRUE or FALSE)
            USE_MULT  => "NONE",                  -- Select multiplier usage ("MULTIPLY", "DYNAMIC", or "NONE")
            USE_SIMD  => "ONE48",                 -- SIMD selection ("ONE48", "TWO24", "FOUR12")
            -- Pattern Detector Attributes: Pattern Detection Configuration
            AUTORESET_PATDET  => "NO_RESET",      -- "NO_RESET", "RESET_MATCH", "RESET_NOT_MATCH" 
            MASK              => X"3fffffffffff", -- 48-bit mask value for pattern detect (1=ignore)
            PATTERN           => X"000000000000", -- 48-bit pattern match for pattern detect
            SEL_MASK          => "MASK",          -- "C", "MASK", "ROUNDING_MODE1", "ROUNDING_MODE2" 
            SEL_PATTERN       => "PATTERN",       -- Select pattern value ("PATTERN" or "C")
            USE_PATTERN_DETECT=> "NO_PATDET",     -- Enable pattern detect ("PATDET" or "NO_PATDET")
            -- Register Control Attributes: Pipeline Register Configuration
            ACASCREG      => 0,                   -- Number of pipeline stages between A/ACIN and ACOUT (0, 1 or 2)
            ADREG         => 1,                   -- Number of pipeline stages for pre-adder (0 or 1).  -- This is done to improve power characteristics as per Vivado recommendation.
            ALUMODEREG    => 0,                   -- Number of pipeline stages for ALUMODE (0 or 1)
            AREG          => 0,                   -- Number of pipeline stages for A (0, 1 or 2)
            BCASCREG      => 0,                   -- Number of pipeline stages between B/BCIN and BCOUT (0, 1 or 2)
            BREG          => 0,                   -- Number of pipeline stages for B (0, 1 or 2)
            CARRYINREG    => 0,                   -- Number of pipeline stages for CARRYIN (0 or 1)
            CARRYINSELREG => 0,                   -- Number of pipeline stages for CARRYINSEL (0 or 1)
            CREG          => 0,                   -- Number of pipeline stages for C (0 or 1)
            DREG          => 1,                   -- Number of pipeline stages for D (0 or 1)           -- This is done to improve power characteristics as per Vivado recommendation.
            INMODEREG     => 0,                   -- Number of pipeline stages for INMODE (0 or 1)
            MREG          => 0,                   -- Number of multiplier pipeline stages (0 or 1)
            OPMODEREG     => 0,                   -- Number of pipeline stages for OPMODE (0 or 1)
            PREG          => 0                    -- Number of pipeline stages for P (0 or 1)
        )
        port map (
            CARRYOUT(3) => data_out(j),                     -- 4-bit output: Carry output
            CARRYOUT(2 downto 0) => dummydsp(j)(2 downto 0),-- 4-bit output: Carry output
            P => dsp_out(j),                                -- 48-bit output: Primary data output

            ACIN          => (others => '0'), -- 30-bit input: A cascade data input
            BCIN          => (others => '0'), -- 18-bit input: B cascade input
            CARRYCASCIN   => '0',             -- 1-bit input: Cascade carry input
            MULTSIGNIN    => '0',             -- 1-bit input: Multiplier sign input
            PCIN          => (others => '0'), -- 48-bit input: P cascade input

            ALUMODE       => ctrlAluDSP(j/2), -- 4-bit input: ALU control input -- Reading the code from C:\Xilinx\Vivado\2022.2\data\vhdl\src\unisims\primitive\DSP48E1.vhd, 
                                                                                -- the OR operation does not use the carry, so it needs to be an arithmetic operation.
                                                                                -- For which one exactly, see doc/.
            CARRYINSEL    => "000",           -- 3-bit input: Carry select input
            CLK           => I_clock,         -- 1-bit input: Clock input
            INMODE        => "00000",         -- 5-bit input: INMODE control input
            OPMODE        => "0110011",       -- 7-bit input: Operation mode input

            A=>dspInAux(j)(95 downto 66),
            B=>dspInAux(j)(65 downto 48),
            C=>dspInAux(j)(47 downto 0),

            CARRYIN => '1',                 -- 1-bit input: Carry input signal
            D => (others => '0'),           -- 25-bit input: D data input
    
            CEA1          => '0', -- 1-bit input: Clock enable input for 1st stage AREG
            CEA2          => '0', -- 1-bit input: Clock enable input for 2nd stage AREG
            CEAD          => '0', -- 1-bit input: Clock enable input for ADREG
            CEALUMODE     => '0', -- 1-bit input: Clock enable input for ALUMODE
            CEB1          => '0', -- 1-bit input: Clock enable input for 1st stage BREG
            CEB2          => '0', -- 1-bit input: Clock enable input for 2nd stage BREG
            CEC           => '0', -- 1-bit input: Clock enable input for CREG
            CECARRYIN     => '0', -- 1-bit input: Clock enable input for CARRYINREG
            CECTRL        => '0', -- 1-bit input: Clock enable input for OPMODEREG and CARRYINSELREG
            CED           => '0', -- 1-bit input: Clock enable input for DREG
            CEINMODE      => '0', -- 1-bit input: Clock enable input for INMODEREG
            CEM           => '0', -- 1-bit input: Clock enable input for MREG
            CEP           => '0', -- 1-bit input: Clock enable input for PREG
            RSTA          => '0', -- 1-bit input: Reset input for AREG
            RSTALLCARRYIN => '0', -- 1-bit input: Reset input for CARRYINREG
            RSTALUMODE    => '0', -- 1-bit input: Reset input for ALUMODEREG
            RSTB          => '0', -- 1-bit input: Reset input for BREG
            RSTC          => '0', -- 1-bit input: Reset input for CREG
            RSTCTRL       => '0', -- 1-bit input: Reset input for OPMODEREG and CARRYINSELREG
            RSTD          => '0', -- 1-bit input: Reset input for DREG and ADREG
            RSTINMODE     => '0', -- 1-bit input: Reset input for INMODEREG
            RSTM          => '0', -- 1-bit input: Reset input for MREG
            RSTP          => '0'  -- 1-bit input: Reset input for PREG
        );

    end generate;

    -- Output for GPRs
    outputs.data<=data_out;
    -- Output for processor in case of exception. Unused at the moment.
    outputs.exception <= exceptionW or exceptionR or exceptionRO or exceptionPriv;

end lvt_modified;